def car_race_collision(n: int):
    left_cars = [i for i in range(n)]  # Initialize positions of cars moving left to right
    right_cars = [i for i in range(2*n, n, -1)]  # Initialize positions of cars moving right to left

    collisions = 0
    for i in range(n):
        time_to_collision = (right_cars[i] - left_cars[i]) / 2  # Calculate time to collision
        if time_to_collision >= 0:
            collisions += 1  # Increment collision count if collision occurs

    return collisions

