def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def calculate_changes(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            changes += abs(sub_arr[i] - sub_arr[-i - 1])
        return changes

    if len(arr) <= 1:
        return 0

    middle = len(arr) // 2
    left_sub_arr = arr[:middle]
    right_sub_arr = arr[middle + len(arr) % 2:]

    if is_palindromic(arr):
        return 0

    return min(calculate_changes(left_sub_arr), calculate_changes(right_sub_arr))

